pub use ferrumc_physics::Motion;

/// The group a type spawns and is counted in.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum MobCategory {
    Monster,
    Creature,
    Ambient,
    Axolotls,
    UndergroundWaterCreature,
    WaterCreature,
    WaterAmbient,
    Misc,
}

/// What each category allows.
#[derive(Debug, Clone, Copy)]
pub struct CategoryDef {
    /// The name the data files use.
    pub name: &'static str,
    /// How many of this group may be in one chunk before no more spawn, or nothing
    /// where there is no limit.
    pub max_per_chunk: Option<u32>,
    /// Whether it counts as peaceful, which decides whether the difficulty removes it.
    pub friendly: bool,
    /// Whether one stays once spawned rather than despawning when nobody is near.
    pub persistent: bool,
    /// Past this many blocks from every player, one despawns at once.
    pub despawn_distance: u32,
    /// Within this many, one never despawns.
    pub no_despawn_distance: u32,
}

impl MobCategory {
    /// What this category allows.
    #[must_use]
    pub const fn def(self) -> &'static CategoryDef {
        &CATEGORIES[self as usize]
    }
}

