/// Where a mob of a type may stand for it to spawn there.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SpawnPlacement {
    /// Anywhere at all.
    NoRestrictions,
    /// On a block that will hold it.
    OnGround,
    InWater,
    InLava,
}

/// Which surface a spawn attempt is measured against.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SpawnHeightmap {
    MotionBlocking,
    MotionBlockingNoLeaves,
}

/// What one entity type is.
#[derive(Debug, Clone, Copy)]
pub struct EntityDef {
    /// The name the registry gives it, namespace included.
    pub name: &'static str,
    pub category: MobCategory,
    /// How wide it is; an entity's box is square in plan.
    pub width: f32,
    pub height: f32,
    /// How far up the box it looks from.
    pub eye_height: f32,
    /// Whether the box stays this size whatever the entity is doing.
    pub fixed_size: bool,
    /// How many chunks away a client is still told about it.
    pub tracking_range: u8,
    /// How many ticks between updates, or nothing where it is never updated again.
    pub update_interval: Option<u32>,
    /// Whether it is written with the chunk it is in.
    pub serialize: bool,
    /// Whether a command may make one.
    pub summon: bool,
    pub fire_immune: bool,
    /// Whether it may spawn beyond the usual distance from a player.
    pub spawn_far_from_player: bool,
    /// Whether it survives the peaceful difficulty.
    pub allowed_in_peaceful: bool,
    pub placement: SpawnPlacement,
    pub heightmap: SpawnHeightmap,
    /// What a living one starts with, or nothing where it is not a living entity.
    pub max_health: Option<f32>,
    /// How a tick moves one of these when nothing else does.
    pub motion: Motion,
}

